import dataclasses
from typing import Dict, Any

@dataclasses.dataclass
class EncryptionRequest:
    plaintext: str
    key_id: str

@dataclasses.dataclass
class EncryptionResponse:
    ciphertext: bytes
    key_id: str
    encryption_context: Dict[str, str]

@dataclasses.dataclass
class DecryptionRequest:
    ciphertext: bytes
    key_id: str
    encryption_context: Dict[str, str]

@dataclasses.dataclass
class DecryptionResponse:
    plaintext: str
    key_id: str
    encryption_context: Dict[str, str]

import os
import boto3

def get_kms_client():
    region_name = os.environ.get("AWS_REGION", "us-east-1")
    return boto3.client("kms", region_name=region_name)

from security_client import get_kms_client
from security_models import EncryptionRequest, EncryptionResponse

def encrypt_payload(request: EncryptionRequest) -> EncryptionResponse:
    kms_client = get_kms_client()
    response = kms_client.encrypt(
        KeyId=request.key_id,
        Plaintext=request.plaintext.encode('utf-8'),
        # EncryptionContext={ 'Example': 'ExampleContext' }
    )
    return EncryptionResponse(
        ciphertext=response['CiphertextBlob'],
        key_id=request.key_id,
        encryption_context={}
    )

from security_client import get_kms_client
from security_models import DecryptionRequest, DecryptionResponse

def decrypt_payload(request: DecryptionRequest) -> DecryptionResponse:
    kms_client = get_kms_client()
    response = kms_client.decrypt(
        CiphertextBlob=request.ciphertext,
        # EncryptionContext={ 'Example': 'ExampleContext' }
    )
    return DecryptionResponse(
        plaintext=response['Plaintext'].decode('utf-8'),
        key_id=request.key_id,
        encryption_context={}
    )

import os
import boto3
from datetime import datetime, timedelta
from typing import List, Dict, Any

def summarize_key_usage(lookup_attribute_key: str = 'EventName', lookup_attribute_value: str = 'Encrypt', hours_ago: int = 24) -> List[Dict[str, Any]]:
    cloudtrail_client = boto3.client('cloudtrail', region_name=os.environ.get("AWS_REGION", "us-east-1"))
    start_time = datetime.now() - timedelta(hours=hours_ago)

    events = []
    paginator = cloudtrail_client.get_paginator('lookup_events')
    response_iterator = paginator.paginate(
        LookupAttributes=[
            {
                'AttributeKey': lookup_attribute_key,
                'AttributeValue': lookup_attribute_value
            },
        ],
        StartTime=start_time,
    )

    for page in response_iterator:
        for event in page['Events']:
            events.append({
                'EventId': event['EventId'],
                'EventName': event['EventName'],
                'Username': event['Username'],
                'EventTime': event['EventTime'].isoformat()
            })
    return events

import os
from googleapiclient import discovery

def check_payload_safety(text_payload: str) -> dict:
    client = discovery.build(
        "commentanalyzer",
        "v1alpha1",
        developerKey=os.environ.get("PERSPECTIVE_API_KEY"),
        discoveryServiceUrl="https://commentanalyzer.googleapis.com/$discovery/rest?version=v1alpha1",
        static_discovery=False,
    )

    analyze_request = {
        'comment': { 'text': text_payload },
        'requestedAttributes': { 'TOXICITY': {} }
    }

    response = client.comments().analyze(body=analyze_request).execute()
    return response
